  "elevation": [
    {
      "style": "rgba(71, 92, 133, 0.25) 0px 4px 20px 0px, rgba(144, 138, 208, 0.1) 0px 30px 60px 0px",
      "element": "Hero floating UI mockup"
    },
    {
      "style": "rgba(73, 46, 107, 0.14) 0px 3px 16px 0px",
      "element": "Testimonial card / floating panel"
