    {
      "why": "Identical developer-trust posture — cloud-white canvas, generous section gaps, minimal card chrome relying on surface contrast, and a single saturated accent for actions",
      "business": "Vercel"
    },
    {
      "why": "Shared 9999px pill buttons, 16px card radius, periwinkle-tinted ambient shadows on floating elements, and the same flat-icon-in-pastel-circle category pattern",
      "business": "Cal.com"
